OUT = []

def run(tag, code, value):
    t0 = time.time()
    try:
        v = value()
        dt = time.time() - t0
        try:
            tex = str(latex(v))
        except Exception:
            tex = None
        OUT.append(dict(tag=tag, code=code, repr=str(v), tex=tex, secs=round(float(dt), _sage_const_2 ), ok=True))
        print(f"[ok]   {tag:26s} {dt:5.2f}s")
    except Exception as e:
        OUT.append(dict(tag=tag, code=code, repr=f"{type(e).__name__}: {e}", tex=None,
                        secs=round(float(time.time()-t0), _sage_const_2 ), ok=False))
        print(f"[FAIL] {tag:26s} {type(e).__name__}: {e}")

