# the imaginary part above threshold, against the exact formula
def disc_table():
    rows = []
    for x in (_sage_const_5 , _sage_const_9 , _sage_const_16 , _sage_const_100 ):
        im = CC(DiscB(x, _sage_const_1 , _sage_const_1 )).imag()
        pred = RR(pi*sqrt(_sage_const_1  - _sage_const_4 /x))
        rows.append((x, float(im), float(pred), bool(abs(im - pred) < _sage_const_1en12 )))
    return rows
