def selfenergy():
    qed = QED(muons=False, taus=False)
    p = momenta('pp_'); P2 = var('P2_')
    se = topologies(_sage_const_1 , _sage_const_1 , _sage_const_1 , exclude=('tadpoles', 'wf'))
    dA = insert_fields(se, ['A'], ['A'], qed)
    gM = sum(dA.loop_amplitude([p], [p], lambda n, e: n*T.metric(e[_sage_const_0 ], e[_sage_const_1 ]), {'pp_^2': 'P2_'}))
    Pi2 = gM/((_sage_const_3  - _sage_const_2 *eps)*P2)
    return uv_part(Pi2).simplify_full()
run("photon_se", "uv_part(Pi2)  for the QED photon self-energy", selfenergy)

